  const body = blocks.join('\n');
  const lead = filteredLead(providerText, cited, body);
  const pricing = PRICING_QUESTION.test(question) || cited.some(r => /pric/i.test(`${r.id} ${r.title} ${r.topics.join(' ')}`));
